import{_ as a,o,c as t,ag as l}from"./chunks/framework.D4c47gkQ.js";const u=JSON.parse('{"title":"Releasing a new OSRM version","description":"","frontmatter":{},"headers":[],"relativePath":"releasing.md","filePath":"releasing.md"}'),i={name:"releasing.md"};function r(s,e,n,c,d,h){return o(),t("div",null,[...e[0]||(e[0]=[l('<h1 id="releasing-a-new-osrm-version" tabindex="-1">Releasing a new OSRM version <a class="header-anchor" href="#releasing-a-new-osrm-version" aria-label="Permalink to &quot;Releasing a new OSRM version&quot;">​</a></h1><p>We use a <strong>unified semver versioning scheme</strong> for monthly releases: <code>(YYYY-2000).M.patchlevel</code></p><ul><li><strong>Format:</strong> <code>X.M.patchlevel</code> where X = year - 2000, M = month (1-12, no leading zeros)</li><li><strong>Example:</strong> <code>26.4.0</code> represents April 2026, first release</li><li><strong>Git tags:</strong> Prefixed with <code>v</code> (e.g., <code>v26.4.0</code>)</li><li><strong>npm packages:</strong> Unprefixed semver (e.g., <code>26.4.0</code>)</li></ul><h2 id="version-history" tabindex="-1">Version History <a class="header-anchor" href="#version-history" aria-label="Permalink to &quot;Version History&quot;">​</a></h2><p><strong>Previous scheme (ended 2025):</strong> Traditional semantic versioning (v6.0, v6.0.1, v6.0.2, etc.)</p><ul><li>Last release: v6.0.0 in December 2025</li><li>Manual release process</li></ul><p><strong>New scheme (started 2026):</strong> Monthly date-based versioning with automated releases</p><ul><li>First release: v26.1.0 (January 2026)</li><li>Automatic monthly releases on the 1st of each month at 08:00 UTC</li><li>Year offset: 2026 → 26, 2027 → 27, etc.</li><li>Month: 1-12 (no leading zeros), patch: 0-N per month</li></ul><h2 id="versioning-scheme" tabindex="-1">Versioning Scheme <a class="header-anchor" href="#versioning-scheme" aria-label="Permalink to &quot;Versioning Scheme&quot;">​</a></h2><h3 id="format" tabindex="-1">Format <a class="header-anchor" href="#format" aria-label="Permalink to &quot;Format&quot;">​</a></h3><p><strong>Git tags:</strong> <code>vX.M.patchlevel</code> where X = year - 2000, M = 1-12</p><ul><li><strong>X:</strong> Year offset (26 = 2026, 27 = 2027, etc.)</li><li><strong>M:</strong> Month (1-12, no leading zeros)</li><li><strong>patchlevel:</strong> Incremental counter starting at 0 per month (0, 1, 2, ...)</li></ul><p><strong>npm packages:</strong> <code>X.M.patchlevel</code> (same as git tag without the <code>v</code> prefix)</p><h3 id="examples" tabindex="-1">Examples <a class="header-anchor" href="#examples" aria-label="Permalink to &quot;Examples&quot;">​</a></h3><p>Git tags and npm versions for the same release:</p><ul><li>April 2026, 1st release: Git tag <code>v26.4.0</code>, npm <code>26.4.0</code></li><li>April 2026, 2nd release: Git tag <code>v26.4.1</code>, npm <code>26.4.1</code></li><li>May 2026, 1st release: Git tag <code>v26.5.0</code>, npm <code>26.5.0</code></li><li>January 2027, 1st release: Git tag <code>v27.1.0</code>, npm <code>27.1.0</code></li></ul><h2 id="release-compatibility-guarantees" tabindex="-1">Release Compatibility Guarantees <a class="header-anchor" href="#release-compatibility-guarantees" aria-label="Permalink to &quot;Release Compatibility Guarantees&quot;">​</a></h2><h3 id="patch-version-change-new-patchlevel-in-same-month" tabindex="-1">Patch version change (new patchlevel in same month) <a class="header-anchor" href="#patch-version-change-new-patchlevel-in-same-month" aria-label="Permalink to &quot;Patch version change (new patchlevel in same month)&quot;">​</a></h3><ul><li>No change of query parameters or response formats</li><li>Compatible HTTP API</li><li>Compatible C++ library API</li><li>Compatible node-osrm API</li><li>Compatible OSRM datasets</li></ul><h3 id="month-change-new-yyyy-mm" tabindex="-1">Month change (new YYYY-MM) <a class="header-anchor" href="#month-change-new-yyyy-mm" aria-label="Permalink to &quot;Month change (new YYYY-MM)&quot;">​</a></h3><ul><li>May introduce forward-compatible changes: query parameters and response properties may be added in responses, but existing properties may not be changed or removed</li><li>Forward-compatible HTTP API</li><li>Forward-compatible C++ library API</li><li>Forward-compatible node-osrm API</li><li>No compatibility between OSRM datasets (needs new processing)</li></ul><h2 id="conventional-commits" tabindex="-1">Conventional Commits <a class="header-anchor" href="#conventional-commits" aria-label="Permalink to &quot;Conventional Commits&quot;">​</a></h2><p>Pull request titles must follow <a href="https://www.conventionalcommits.org/" target="_blank" rel="noreferrer">Conventional Commits</a> format with types: <code>feat</code>, <code>fix</code>, <code>docs</code>, <code>style</code>, <code>refactor</code>, <code>perf</code>, <code>test</code>, <code>ci</code>, <code>chore</code>, <code>build</code>. This is validated in CI and helps organize the commit history.</p><p>Breaking changes should be indicated with the <code>!</code> suffix in the PR title (e.g., <code>feat!: remove deprecated API</code>) so they are called out in release notes.</p><h2 id="release-management" tabindex="-1">Release Management <a class="header-anchor" href="#release-management" aria-label="Permalink to &quot;Release Management&quot;">​</a></h2><ul><li>The <code>master</code> branch is for development and should always be green</li><li><strong>Automated monthly releases</strong> occur on the <strong>1st of each month at 08:00 UTC</strong></li><li>All changes in master will be automatically released monthly</li><li>No release candidates are used; the master branch is the quality gate</li><li>Patch versions within the same month can be released manually at any time</li></ul><h2 id="automated-release-process" tabindex="-1">Automated Release Process <a class="header-anchor" href="#automated-release-process" aria-label="Permalink to &quot;Automated Release Process&quot;">​</a></h2><p>Releases are created automatically every month on a scheduled basis:</p><ol><li>A GitHub Actions workflow runs on the 1st of each month at 08:00 UTC</li><li>Version is calculated as <code>(YYYY-2000).M.patchlevel</code> with M = 1-12 (no leading zeros)</li><li><code>package.json</code> and <code>package-lock.json</code> versions are updated</li><li>A git tag is created and pushed (e.g., <code>v26.4.0</code>)</li><li>A GitHub Release is published with auto-generated release notes</li><li>The package is published to npm (format: <code>26.4.0</code> without <code>v</code> prefix)</li></ol><h2 id="manual-release-trigger" tabindex="-1">Manual Release Trigger <a class="header-anchor" href="#manual-release-trigger" aria-label="Permalink to &quot;Manual Release Trigger&quot;">​</a></h2><p>You can also trigger a release manually on any branch:</p><ol><li>Go to <strong>Actions</strong> → <strong>Monthly Release</strong> workflow</li><li>Click <strong>Run workflow</strong></li><li>Select your branch (defaults to <code>master</code>)</li><li>Optionally override the version (format: <code>X.M.patchlevel</code> with M = 1-12, e.g., <code>26.4.0</code>)</li><li>Click <strong>Run workflow</strong></li></ol><p>This is useful for:</p><ul><li>Out-of-schedule patch releases within the same month</li><li>Emergency releases from other branches</li><li>Backports to older versions</li></ul><h2 id="release-checklist" tabindex="-1">Release Checklist <a class="header-anchor" href="#release-checklist" aria-label="Permalink to &quot;Release Checklist&quot;">​</a></h2><p>When releasing (automated or manual):</p><ol><li>✅ All GitHub Actions CI checks pass</li><li>✅ The target branch is in a releasable state</li><li>✅ For manual releases: verify the version format is correct (<code>X.M.patchlevel</code> with month 1-12, e.g., <code>26.4.0</code>)</li><li>✅ The release is created automatically with: <ul><li>Git tag</li><li>GitHub Release (with auto-generated release notes)</li><li>npm publication</li></ul></li></ol><h2 id="after-release" tabindex="-1">After Release <a class="header-anchor" href="#after-release" aria-label="Permalink to &quot;After Release&quot;">​</a></h2><p>No additional manual steps are required. The automated workflow handles:</p><ul><li>Version bumping in <code>package.json</code></li><li>Git commit and tag creation</li><li>GitHub Release publishing</li><li>npm package publication</li></ul><p>For non-automated releases, monitor:</p><ul><li>GitHub Actions to verify the release completed successfully</li><li>npm registry to confirm the new version is published</li></ul>',42)])])}const p=a(i,[["render",r]]);export{u as __pageData,p as default};
